// Phase 8: Batch API Engine for Cross-Layer Communication
// 목적: API 호출을 배치 처리하여 네트워크 오버헤드 감소

use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// 배치 요청 항목
#[derive(Clone, Debug)]
pub struct BatchItem<T> {
    pub id: u64,
    pub data: T,
    pub timestamp: Instant,
}

/// 배치 요청 컨테이너
#[derive(Debug)]
pub struct BatchRequest<T> {
    items: VecDeque<BatchItem<T>>,
    max_batch_size: usize,
    max_wait_duration: Duration,
    created_at: Instant,
}

impl<T: Clone> BatchRequest<T> {
    /// 새로운 배치 요청 생성
    pub fn new(max_batch_size: usize, max_wait_duration: Duration) -> Self {
        BatchRequest {
            items: VecDeque::with_capacity(max_batch_size),
            max_batch_size,
            max_wait_duration,
            created_at: Instant::now(),
        }
    }

    /// 항목 추가
    pub fn add_item(&mut self, id: u64, data: T) -> bool {
        if self.items.len() >= self.max_batch_size {
            return false; // 배치 가득 참
        }
        self.items.push_back(BatchItem {
            id,
            data,
            timestamp: Instant::now(),
        });
        Ok(true).unwrap_or(false)
    }

    /// 배치 실행 가능 여부 확인
    pub fn is_ready(&self) -> bool {
        if self.items.is_empty() {
            return false;
        }

        // 조건 1: 배치 크기 도달
        if self.items.len() >= self.max_batch_size {
            return true;
        }

        // 조건 2: 대기 시간 초과
        if self.created_at.elapsed() >= self.max_wait_duration {
            return true;
        }

        false
    }

    /// 배치 항목 개수
    pub fn len(&self) -> usize {
        self.items.len()
    }

    /// 배치 비어있음 확인
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    /// 배치 항목 반환 (소비)
    pub fn drain(&mut self) -> Vec<BatchItem<T>> {
        self.items.drain(..).collect()
    }

    /// 배치 항목 참조만 반환
    pub fn iter(&self) -> impl Iterator<Item = &BatchItem<T>> {
        self.items.iter()
    }

    /// 배치 크기 리셋
    pub fn reset(&mut self) {
        self.items.clear();
        self.created_at = Instant::now();
    }
}

/// 배치 처리 엔진 (Foundation 계층)
pub struct BatchEngine<T> {
    queue: Arc<Mutex<VecDeque<T>>>,
    batch_config: BatchConfig,
    item_counter: Arc<Mutex<u64>>,
}

#[derive(Clone, Debug)]
pub struct BatchConfig {
    pub max_batch_size: usize,
    pub max_wait_ms: u64,
    pub max_queue_size: usize,
}

impl Default for BatchConfig {
    fn default() -> Self {
        BatchConfig {
            max_batch_size: 100,
            max_wait_ms: 50,
            max_queue_size: 10000,
        }
    }
}

impl<T: Clone + Send + 'static> BatchEngine<T> {
    pub fn new(config: BatchConfig) -> Self {
        BatchEngine {
            queue: Arc::new(Mutex::new(VecDeque::with_capacity(config.max_queue_size))),
            batch_config: config,
            item_counter: Arc::new(Mutex::new(0)),
        }
    }

    /// 큐에 항목 추가
    pub fn enqueue(&self, item: T) -> Result<u64, String> {
        let mut queue = self.queue.lock().unwrap();

        if queue.len() >= self.batch_config.max_queue_size {
            return Err("Queue is full".to_string());
        }

        queue.push_back(item);

        let mut counter = self.item_counter.lock().unwrap();
        *counter += 1;
        Ok(*counter)
    }

    /// 배치 추출
    pub fn extract_batch(&self) -> Vec<T> {
        let mut queue = self.queue.lock().unwrap();
        let batch_size = std::cmp::min(
            self.batch_config.max_batch_size,
            queue.len(),
        );

        queue.drain(0..batch_size).collect()
    }

    /// 큐 크기 확인
    pub fn queue_size(&self) -> usize {
        self.queue.lock().unwrap().len()
    }

    /// 처리된 항목 수
    pub fn processed_count(&self) -> u64 {
        *self.item_counter.lock().unwrap()
    }
}

/// 배치 실행기 (System 계층 통합용)
pub struct BatchExecutor<T, R> {
    engine: BatchEngine<T>,
    batch_size: usize,
    executor_fn: Arc<dyn Fn(Vec<T>) -> Vec<R> + Send + Sync>,
}

impl<T: Clone + Send + 'static, R: Send + 'static> BatchExecutor<T, R> {
    pub fn new<F>(engine: BatchEngine<T>, batch_size: usize, executor_fn: F) -> Self
    where
        F: Fn(Vec<T>) -> Vec<R> + Send + Sync + 'static,
    {
        BatchExecutor {
            engine,
            batch_size,
            executor_fn: Arc::new(executor_fn),
        }
    }

    /// 배치 실행 (동기)
    pub fn execute(&self) -> Vec<R> {
        let batch = self.engine.extract_batch();
        if batch.is_empty() {
            return Vec::new();
        }
        (self.executor_fn)(batch)
    }

    /// 배치 통계
    pub fn stats(&self) -> BatchStats {
        BatchStats {
            queue_size: self.engine.queue_size(),
            processed_count: self.engine.processed_count(),
            batch_size: self.batch_size,
        }
    }
}

#[derive(Debug, Clone)]
pub struct BatchStats {
    pub queue_size: usize,
    pub processed_count: u64,
    pub batch_size: usize,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_batch_request_add_items() {
        let mut batch = BatchRequest::new(3, Duration::from_millis(100));
        assert!(batch.add_item(1, "data1"));
        assert!(batch.add_item(2, "data2"));
        assert!(batch.add_item(3, "data3"));
        assert_eq!(batch.len(), 3);
    }

    #[test]
    fn test_batch_request_ready() {
        let mut batch = BatchRequest::new(2, Duration::from_millis(100));
        batch.add_item(1, "a");
        assert!(!batch.is_ready());
        batch.add_item(2, "b");
        assert!(batch.is_ready()); // 크기 도달
    }

    #[test]
    fn test_batch_engine_enqueue() {
        let engine = BatchEngine::new(BatchConfig::default());
        assert_eq!(engine.enqueue("item1").unwrap(), 1);
        assert_eq!(engine.enqueue("item2").unwrap(), 2);
        assert_eq!(engine.queue_size(), 2);
    }

    #[test]
    fn test_batch_executor() {
        let engine = BatchEngine::new(BatchConfig {
            max_batch_size: 3,
            max_wait_ms: 50,
            max_queue_size: 100,
        });

        engine.enqueue(1).unwrap();
        engine.enqueue(2).unwrap();
        engine.enqueue(3).unwrap();

        let executor = BatchExecutor::new(engine, 3, |items| {
            items.iter().map(|&x| x * 2).collect()
        });

        let results = executor.execute();
        assert_eq!(results, vec![2, 4, 6]);
    }

    #[test]
    fn test_batch_stats() {
        let engine = BatchEngine::new(BatchConfig::default());
        engine.enqueue("a").unwrap();
        engine.enqueue("b").unwrap();

        let executor = BatchExecutor::new(engine, 10, |_| vec![]);
        let stats = executor.stats();

        assert_eq!(stats.queue_size, 2);
        assert_eq!(stats.processed_count, 2);
    }
}
